package tray

import (
	"encoding/base64"
	"log"
)

var (
	iconActive   = mustDecodePNG("")
	iconInactive = mustDecodePNG("")
)

func mustDecodePNG(b64 string) []byte {
	data, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		log.Fatalf("internal/tray: invalid base64 png: %v", err)
	}
	return data
}
